/* Requisitos de descarga: respeta la paleta Liquid Glass original */
.tb-gate{margin-top:24px;padding:18px;border:1px solid rgba(124,156,255,.42);border-radius:23px;background:linear-gradient(145deg,rgba(18,28,61,.72),rgba(12,15,34,.82));box-shadow:0 10px 34px rgba(65,88,210,.12),inset 0 1px 0 rgba(255,255,255,.08)}
.tb-gate-title{margin:0 0 6px!important;font-size:21px!important;color:#f5f6ff}
.tb-gate-subtitle{margin:0 0 16px!important;color:#cbd3e9;font-size:13px}
.tb-gate-step{display:flex;align-items:center;gap:12px;padding:13px;margin-top:10px;border:1px solid rgba(133,151,255,.34);border-radius:17px;background:rgba(255,255,255,.045);min-width:0}
.tb-gate-icon{width:42px;height:42px;flex:0 0 42px;display:grid;place-items:center;border-radius:13px;color:#c6b5ff;font-size:22px;background:rgba(130,92,255,.17);border:1px solid rgba(153,123,255,.45)}
.tb-gate-copy{flex:1;min-width:0;display:flex;flex-direction:column;gap:4px}.tb-gate-copy b{font-size:14px;color:#fff}.tb-ad-counter{display:inline-flex;align-items:center;margin-left:8px;padding:3px 9px;border-radius:999px;background:rgba(130,92,255,.22);border:1px solid rgba(153,123,255,.55);color:#d8caff;font-size:12px;font-weight:800;letter-spacing:.3px;vertical-align:middle}.tb-gate-copy small{font-size:11px;line-height:1.45;color:#cbd3e9}
.tb-gate-action{flex:0 0 auto;display:inline-flex;align-items:center;justify-content:center;padding:10px 13px;border-radius:999px;border:1px solid rgba(147,129,255,.62);background:rgba(99,91,215,.18);color:#fff!important;text-decoration:none!important;font:inherit;font-size:12px;font-weight:700;cursor:pointer}
.tb-gate-step.is-locked{opacity:.55}.tb-gate-step.is-locked .tb-gate-action{pointer-events:none}.tb-gate-action.is-disabled{opacity:.8}.tb-gate-footnote{margin:13px 2px 0!important;text-align:center;font-size:11px;color:#9faad0}
@media(max-width:600px){.tb-gate{padding:13px;border-radius:19px}.tb-gate-step{gap:10px;padding:13px;flex-wrap:wrap}.tb-gate-icon{width:44px;height:44px;flex:0 0 44px;font-size:24px}.tb-gate-copy{flex:1 1 calc(100% - 66px);min-width:0}.tb-gate-copy b{font-size:16px;line-height:1.3}.tb-ad-counter{font-size:13px}.tb-gate-copy small{font-size:13px;line-height:1.45}.tb-gate-action{width:100%;min-height:48px;padding:13px 16px;font-size:15px;border-radius:15px;box-sizing:border-box}.tb-gate-title{font-size:22px!important}.tb-gate-subtitle{font-size:14px;line-height:1.5}}

head.b:template-skin:

body#layout .hidden,
body#layout .invisible {
  display: inherit;
}
body#layout .navigation {
  display: none;
}
body#layout .page,
body#layout .sidebar_top,
body#layout .sidebar_bottom {
  display: inline-block;
  left: inherit;
  position: relative;
  vertical-align: top;
}
body#layout .page {
  float: right;
  margin-left: 20px;
  width: 55%;
}
body#layout .sidebar-container {
  float: right;
  width: 40%;
}
body#layout .hamburger-menu {
  display: none;
}

body.script:
//

function tbResetGate(){
  var gate=document.querySelector('.tb-gate'); if(!gate)return;
  var counter=gate.querySelector('[data-ad-counter]'); if(counter)counter.textContent='0/5';
  gate.querySelectorAll('.tb-gate-step').forEach(function(step,i){step.classList.toggle('is-locked',i>0);});
  var dl=gate.querySelector('[data-gate-download]'); if(dl){dl.textContent='Descargar este archivo';dl.classList.remove('is-disabled');dl.removeAttribute('aria-disabled');}
  gate.dataset.stage='1';
}
document.addEventListener('click',function(e){
  var gate=document.querySelector('.tb-gate'); if(!gate)return;
  var action=e.target.closest('[data-gate-ad]');
  if(action){e.preventDefault();alert('Los anuncios todavía no están conectados a un proveedor. No se puede verificar ni completar este paso hasta configurar la red publicitaria.');return;}
  var stepAction=e.target.closest('.tb-gate-step .tb-gate-action'); if(!stepAction)return;
  if(stepAction.hasAttribute('data-gate-download') && stepAction.getAttribute('aria-disabled')==='true'){e.preventDefault();return;}
  var step=stepAction.closest('.tb-gate-step'); if(step.classList.contains('is-locked')){e.preventDefault();return;}
  var n=Number(step.getAttribute('data-step'));
  if(n===1||n===2){
    // Opens the destination normally. On the next tap, advances locally; no progress is stored.
    if(step.dataset.visited==='1'){
      // En el segundo toque también vuelve a abrir YouTube y además habilita el paso siguiente.
      e.preventDefault();
      var destination=stepAction.getAttribute('href');
      if(destination && destination!=='#') window.open(destination,'_blank','noopener,noreferrer');
      step.dataset.visited='';
      var next=gate.querySelector('[data-step="'+(n+1)+'"]'); if(next)next.classList.remove('is-locked');
      gate.dataset.stage=String(n+1);
    }else{step.dataset.visited='1';}
  }
  if(n===4){stepAction.setAttribute('target','_blank');stepAction.setAttribute('rel','noopener noreferrer');}
});

function tbOpenDetail(card){
  tbResetGate();
  var modal=document.getElementById('tb-detail-modal');
  var key=card.getAttribute('data-texture');
  var title=card.getAttribute('data-title');
  var cat=card.getAttribute('data-category');
  var ver=card.getAttribute('data-version');
  var likes=card.getAttribute('data-likes');
  var desc=card.getAttribute('data-description');
  var downloadUrl=card.getAttribute('data-download')||card.getAttribute('data-drive-view')||'#';
  var img=card.querySelector('img').src;
  /* La portada del detalle de Sakura/Armas EVOS es independiente de la portada de inicio. */
  var detailCover=card.getAttribute('data-detail-cover');
  if(!detailCover && (key==='sakura' || key==='armas-evos' || key==='armas_evos' || key==='evos')){
    detailCover='https://encrypted-tbn0.gstatic.com/images?q=tbn:ANd9GcTIfhArxvNKXzYh1gfwFiulOrg6pUarf3EH0oJPm19ThHlD7DSK62nrPpi0&s=10';
  }
  var downloadButton=document.querySelector('[data-gate-download]');
  if(downloadButton){downloadButton.setAttribute('href',downloadUrl);downloadButton.setAttribute('target','_blank');downloadButton.setAttribute('rel','noopener noreferrer');downloadButton.textContent='Descargar este archivo';downloadButton.classList.add('is-disabled');downloadButton.setAttribute('aria-disabled','true');}
  var coverEl=document.getElementById('tb-detail-cover');
  if(coverEl){coverEl.src=detailCover||img;coverEl.alt=title||'Portada de textura';}
  document.getElementById('tb-detail-title').textContent=title||'Textura';
  document.getElementById('tb-detail-category').textContent=cat||'Texturas';
  document.getElementById('tb-detail-version').textContent='♧ Versión '+(ver||'1.00');
  document.getElementById('tb-detail-likes').textContent='♡ '+(likes||'—');
  document.getElementById('tb-detail-description').textContent=desc||'Sin descripción.';
  [1,2,3].forEach(function(i){
    var galleryUrl=card.getAttribute('data-gallery-'+i)||'';
    var galleryImage=document.getElementById('tb-gallery-'+i);
    if(galleryImage){if(galleryUrl){galleryImage.src=galleryUrl;galleryImage.alt='Captura '+i+' de '+(title||'la textura');galleryImage.style.display='';}else{galleryImage.removeAttribute('src');galleryImage.alt='';galleryImage.style.display='none';}}
  });
  modal.classList.add('open');modal.setAttribute('aria-hidden','false');document.body.style.overflow='hidden';
}
function tbCloseDetail(){var m=document.getElementById('tb-detail-modal');m.classList.remove('open');m.setAttribute('aria-hidden','true');document.body.style.overflow='';}
document.addEventListener('DOMContentLoaded',function(){
  document.querySelectorAll('.tb-texture-card').forEach(function(card){card.addEventListener('click',function(e){e.preventDefault();tbOpenDetail(card);});});
  var catLinks=document.querySelectorAll('.tb-categories a');
  catLinks.forEach(function(link){link.addEventListener('click',function(e){
    var href=link.getAttribute('href')||'';
    if(href.indexOf('/search/label/')===0){e.preventDefault();var wanted=decodeURIComponent(href.split('/search/label/')[1]).toLowerCase();document.querySelectorAll('.tb-texture-card').forEach(function(card){var c=(card.getAttribute('data-category')||'').toLowerCase();card.style.display=(c===wanted || (wanted==='freestyle' && c==='freestyle') || (wanted==='fútbol' && c==='fútbol'))?'flex':'none';});document.getElementById('tb-showcase').scrollIntoView({behavior:'smooth'});}
    else if(href==='/search'){e.preventDefault();document.querySelectorAll('.tb-texture-card').forEach(function(card){card.style.display='flex';});document.getElementById('tb-showcase').scrollIntoView({behavior:'smooth'});}
  });});
  var bottom=document.querySelectorAll('#tb-bottom-nav a');
  bottom.forEach(function(a){if((a.textContent||'').toLowerCase().indexOf('buscar')!==-1){a.addEventListener('click',function(e){e.preventDefault();var q=prompt('¿Qué textura querés buscar?');if(q){document.querySelectorAll('.tb-texture-card').forEach(function(card){card.style.display=(card.innerText.toLowerCase().indexOf(q.toLowerCase())!==-1)?'flex':'none';});document.getElementById('tb-showcase').scrollIntoView({behavior:'smooth'});}});}});
  var modal=document.getElementById('tb-detail-modal');modal.addEventListener('click',function(e){if(e.target===modal)tbCloseDetail();});
  document.addEventListener('keydown',function(e){if(e.key==='Escape')tbCloseDetail();});
});
//

//
// Team Blog 1646: sincroniza publicaciones del panel con tarjetas Liquid Glass.
(function(){
 function decode(s){var d=document.createElement('textarea');d.innerHTML=s||'';return d.value;}
 function safeUrl(u){try{var x=new URL(u,location.href);return (x.protocol==='https:'||x.protocol==='http:')?x.href:''}catch(e){return ''}}
 function addCard(d){
  var list=document.querySelector('#tb-showcase .tb-texture-list');
  if(!list||!d.title||!d.download||!d.cover)return;
  var slug=(d.title+'').toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/[^a-z0-9]+/g,'-').replace(/^-|-$/g,'');
  var cover=safeUrl(d.cover),detail=safeUrl(d.detail)||cover,download=safeUrl(d.download);
  if(!cover||!download)return;
  // Si ya existe una tarjeta fija con el mismo título, completarla con la publicación
  // en vez de descartar la publicación y dejarla solamente como entrada grande.
  var existing=Array.from(list.querySelectorAll('.tb-texture-card')).find(function(c){return (c.getAttribute('data-title')||'').trim().toLowerCase()===d.title.trim().toLowerCase()});
  if(existing){
    existing.setAttribute('data-texture',slug||existing.getAttribute('data-texture')||'texture');
    existing.setAttribute('data-category',d.category||existing.getAttribute('data-category')||'Texturas');
    existing.setAttribute('data-version',d.version||'1.00');
    existing.setAttribute('data-download',download);existing.setAttribute('data-drive-view',download);
    existing.setAttribute('data-description',d.description||'');existing.setAttribute('data-detail-cover',detail);
    (d.gallery||[]).slice(0,3).forEach(function(u,i){var valid=safeUrl(u);if(valid)existing.setAttribute('data-gallery-'+(i+1),valid);else existing.removeAttribute('data-gallery-'+(i+1))});
    var oldImg=existing.querySelector('.tb-thumb');if(oldImg){oldImg.src=cover;oldImg.alt=d.title;oldImg.style.visibility='';}
    var oldTag=existing.querySelector('.tb-tag');if(oldTag)oldTag.textContent=d.category||'Texturas';
    var oldTitle=existing.querySelector('.tb-card-title');if(oldTitle)oldTitle.textContent=d.title;
    var oldMeta=existing.querySelector('.tb-card-meta');if(oldMeta){var spans=oldMeta.querySelectorAll('span');if(spans[0])spans[0].textContent='Versión '+(d.version||'1.00');}
    return;
  }
  var baseSlug=slug||'texture', uniqueSlug=baseSlug, suffix=2;while(list.querySelector('[data-texture="'+uniqueSlug.replace(/"/g,'')+'"]')){uniqueSlug=baseSlug+'-'+suffix++;}
  var a=document.createElement('a');
  a.href='#';a.className='tb-texture-card';
  a.setAttribute('data-texture',uniqueSlug+'-'+String(Date.now()).slice(-5));
  a.setAttribute('data-title',d.title);a.setAttribute('data-category',d.category||'Texturas');
  a.setAttribute('data-version',d.version||'1.00');a.setAttribute('data-likes','—');
  a.setAttribute('data-download',download);a.setAttribute('data-drive-view',download);
  a.setAttribute('data-description',d.description||'');a.setAttribute('data-detail-cover',detail);
  (d.gallery||[]).slice(0,3).forEach(function(u,i){var valid=safeUrl(u);if(valid)a.setAttribute('data-gallery-'+(i+1),valid)});
  var img=document.createElement('img');img.className='tb-thumb';img.src=cover;img.alt=d.title;img.loading='lazy';
  img.onerror=function(){this.style.visibility='hidden'};
  var info=document.createElement('div');info.className='tb-card-info';
  var tag=document.createElement('div');tag.className='tb-tag';tag.textContent=d.category||'Texturas';
  var title=document.createElement('div');title.className='tb-card-title';title.textContent=d.title;
  var meta=document.createElement('div');meta.className='tb-card-meta';
  var ver=document.createElement('span');ver.textContent='Versión '+(d.version||'1.00');
  var type=document.createElement('span');type.textContent='ZIP / Drive';meta.append(ver,type);info.append(tag,title,meta);
  var ch=document.createElement('span');ch.className='tb-chevron';ch.textContent='›';
  a.append(img,info,ch);
  a.addEventListener('click',function(e){e.preventDefault();if(typeof window.tbOpenDetail==='function')window.tbOpenDetail(a)});
  list.insertBefore(a,list.firstChild);
 }
 function hidePostForEntry(entry, marker){
  var url='';(entry.link||[]).some(function(l){if(l.rel==='alternate'&&l.href){url=l.href;return true}return false});
  var title=(entry.title&&entry.title.$t||'').trim();
  var post=null;
  // Primero, intentar localizar la entrada por su enlace permanente.
  if(url){var links=Array.from(document.querySelectorAll('a[href]'));var hit=links.find(function(a){try{return new URL(a.href,location.href).href.replace(/\/$/,'')===new URL(url,location.href).href.replace(/\/$/,'')}catch(e){return a.href===url}});if(hit)post=hit.closest('.post-outer, .post-outer-container, article, .hentry, .post');}
  // Si Blogger reescribe el enlace en móvil, localizar la entrada por su título.
  if(!post&&title){var headings=Array.from(document.querySelectorAll('.post-title, .entry-title, h1, h2, h3'));var h=headings.find(function(n){return (n.textContent||'').trim().toLowerCase()===title.toLowerCase()});if(h)post=h.closest('.post-outer, .post-outer-container, article, .hentry, .post');}
  // Último recurso: subir desde el marcador sin ocultar el contenedor entero del blog.
  if(!post&&marker){var node=marker;for(var i=0;i<12&&node&&node.parentElement;i++){node=node.parentElement;if(node.matches&&node.matches('.post-outer, .post-outer-container, article, .hentry, .post')){post=node;break;}}}
  if(post){post.setAttribute('data-tb1646-panel-entry','1');post.style.setProperty('display','none','important');}
 }
 function hideGeneratedPost(){
  document.querySelectorAll('.tb1646-published-item').forEach(function(marker){hidePostForEntry({title:(marker.getAttribute('data-title')||'')},marker)});
 }
 function process(feed){try{
  var entries=(feed&&feed.feed&&Array.isArray(feed.feed.entry))?feed.feed.entry:[];
  var list=document.querySelector('#tb-showcase .tb-texture-list');
  if(list){Array.from(list.querySelectorAll('.tb-texture-card')).forEach(function(card,i){if(!card.getAttribute('data-tb1646-card-id'))card.setAttribute('data-tb1646-card-id','fixed-'+(i+1))})}
  entries.forEach(function(entry){
   var c=entry.content&&entry.content.$t||'';
   if(c.indexOf('tb1646-card-control')>=0){var cd=new DOMParser().parseFromString(c,'text/html').querySelector('.tb1646-card-control');if(cd&&list){(cd.getAttribute('data-deleted')||'').split(',').filter(Boolean).forEach(function(id){var card=list.querySelector('[data-tb1646-card-id="'+id.replace(/"/g,'')+'"]');if(card)card.remove()})}return}
   if(c.indexOf('tb1646-published-item')<0)return;
   var doc=new DOMParser().parseFromString(c,'text/html');
   var el=doc.querySelector('.tb1646-published-item');
   if(!el)return;
   var d={};['title','category','version','download','cover','detail','description'].forEach(function(k){d[k]=el.getAttribute('data-'+k)||''});
   d.title=d.title||(entry.title&&entry.title.$t)||'';
   d.category=d.category||((entry.category||[])[0]&&entry.category[0].term)||'Texturas';
   d.gallery=(el.getAttribute('data-gallery')||'').split('|').map(function(u){return u.trim()}).filter(Boolean);
   // No inventar portadas ni usar una imagen de otra tarjeta: solo crear si la entrada trae sus propios datos.
   if(list&&d.title&&d.cover&&d.download)addCard(d);
   hidePostForEntry(entry,document.querySelector('.tb1646-published-item[data-title="'+(d.title||'').replace(/"/g,'\\"')+'"]'));
  });
  hideGeneratedPost();
 }catch(e){console.warn('Team Blog 1646: no se pudieron leer las tarjetas publicadas',e)}}
 if(!window.__tb1646PanelFeedLoaded){window.__tb1646PanelFeedLoaded=true;window.TB1646PanelFeed=process;var sc=document.createElement('script');sc.src='/feeds/posts/default?alt=json-in-script&max-results=150&callback=TB1646PanelFeed';sc.async=true;sc.onerror=function(){console.warn('Team Blog 1646: no se pudo cargar el feed público de Blogger')};document.head.appendChild(sc);}
 // Blogger puede terminar de pintar las entradas después del feed; observar cambios sin tocar otras publicaciones.
 if(window.MutationObserver&&!window.__tb1646PostObserver){window.__tb1646PostObserver=true;new MutationObserver(function(){hideGeneratedPost()}).observe(document.body,{childList:true,subtree:true});}
 setTimeout(hideGeneratedPost,500);setTimeout(hideGeneratedPost,1500);
})();
//
